// Full-corpus verification for item 23-E: replays every case of the pinned
// evidence corpus (validation/evidence/native/tramo-regression-tests)
// through the transcribed units via the shared replay layer
// (tests/tramo_regression_replay.h, the golden tables generated by
// tools/gen_tramo_regression_tests_golden.py from that corpus) and
// additionally re-reads the raw corpus facts (rt-facts.csv / inputs.csv) to
// cross-qualify the golden table against the captured JVM lines: every ms
// header count, every fr/dr run result token and every pg return token in
// the corpus must agree with the bit-pattern tables the replay consumes.
// A corpus edit that moves any replayed fact therefore fails this sweep
// even before the unit replay runs. Refusal rows (quarterly MS, the Fast
// ami-td/ami-lp/ami-easter and Default calendar-field seam cases) are
// asserted to throw inside the replay.
#include <kalos/tramo_regression_tests.hpp>

#include "../tests/tramo_regression_replay.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

using kalos::replay::as_bits;
using kalos::replay::as_double;

int failures = 0;
int cross = 0;

void fail(const std::string& what) {
    std::cout << "FAIL " << what << std::endl;
    ++cross;
    ++failures;
}

std::vector<std::string> split(const std::string& s, char sep) {
    std::vector<std::string> out;
    std::string cur;
    std::istringstream in(s);
    while (std::getline(in, cur, sep)) out.push_back(cur);
    return out;
}

// One rt-facts.csv / inputs.csv row: id,key,value (quotes stripped).
struct Row {
    std::string id, key, value;
};

std::vector<Row> read_facts(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("cannot open " + path);
    std::vector<Row> out;
    std::string line;
    bool header = true;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        if (header) {
            header = false;
            if (line.rfind("id,", 0) == 0 || line.rfind("\"id\",", 0) == 0)
                continue;
        }
        if (line.size() < 2 || line[0] != '"') {
            fail("corpus row without quoted id: " + line);
            continue;
        }
        const std::string body = line.substr(1);
        const std::size_t q1 = body.find("\",");
        if (q1 == std::string::npos) {
            fail("corpus row without id terminator: " + line);
            continue;
        }
        Row r;
        r.id = body.substr(0, q1);
        std::string rest = body.substr(q1 + 2);
        if (!rest.empty() && rest[0] == '"') rest = rest.substr(1);
        const std::size_t comma = rest.find("\",\"");
        if (comma == std::string::npos) {
            fail("corpus row without key/value separator: " + line);
            continue;
        }
        r.key = rest.substr(0, comma);
        std::string v = rest.substr(comma + 3);
        if (!v.empty() && v.back() == '"') v.pop_back();
        if (!v.empty() && v.back() == '\r') v.pop_back();
        r.value = v;
        out.push_back(r);
    }
    return out;
}

double tok_double(const std::string& tok) {
    if (tok == "NaN") return std::nan("");
    if (tok == "Infinity") return HUGE_VAL;
    if (tok == "-Infinity") return -HUGE_VAL;
    return std::strtod(tok.c_str(), nullptr);
}

std::size_t find_tok(const std::vector<std::string>& t, const std::string& w) {
    for (std::size_t i = 0; i < t.size(); ++i)
        if (t[i] == w) return i;
    return std::string::npos;
}

int tok_int(const std::vector<std::string>& t, const std::string& w) {
    const std::size_t i = find_tok(t, w);
    if (i == std::string::npos || i + 1 >= t.size())
        throw std::runtime_error("token " + w + " missing");
    return std::atoi(t[i + 1].c_str());
}

double tok_d(const std::vector<std::string>& t, const std::string& w) {
    const std::size_t i = find_tok(t, w);
    if (i == std::string::npos || i + 1 >= t.size())
        throw std::runtime_error("token " + w + " missing");
    return tok_double(t[i + 1]);
}

template <typename T>
const T* find_row(const std::vector<T>& rows, const std::string& id,
                  const std::string& key) {
    for (const T& r : rows)
        if (r.id == id && r.key == key) return &r;
    return nullptr;
}

// Cross-qualification: golden tables vs raw corpus tokens.
void cross_qualify(const std::string& corpus) {
    const std::vector<Row> facts = read_facts(corpus + "/rt-facts.csv");

    // Corpus -> golden direction: every case id captured in the corpus must
    // ride the golden tables (a new or renamed case without regeneration
    // fails here).
    std::vector<std::string> golden_ids;
    for (std::size_t i = 0; i < kalos::test::kRtMsN; ++i)
        golden_ids.emplace_back(kalos::test::kRtMs[i].id);
    for (std::size_t i = 0; i < kalos::test::kRtMachinesN; ++i)
        golden_ids.emplace_back(kalos::test::kRtMachines[i].id);
    for (std::size_t i = 0; i < kalos::test::kRtPgN; ++i)
        golden_ids.emplace_back(kalos::test::kRtPg[i].id);
    for (std::size_t i = 0; i < kalos::test::kRtAmN; ++i)
        golden_ids.emplace_back(std::string("am_") + kalos::test::kRtAm[i].spec);
    for (const Row& r : facts) {
        bool known = false;
        for (const std::string& g : golden_ids)
            if (g == r.id) known = true;
        ++cross;
        if (!known) fail("corpus case not in golden: " + r.id);
    }

    for (std::size_t i = 0; i < kalos::test::kRtMsN; ++i) {
        const kalos::test::JvmRtMsCase& c = kalos::test::kRtMs[i];
        const Row* ms = find_row(facts, c.id, "ms");
        if (!ms) {
            fail(std::string(c.id) + ": no ms header row in corpus");
            continue;
        }
        // The first ms row is the header (freq n k m spec mean nx); the
        // consumed k/freq ride the golden; the counts must agree.
        const std::vector<std::string> t = split(ms->value, ' ');
        ++cross;
        if (tok_int(t, "freq") != c.freq)
            fail(std::string(c.id) + ": freq drift");
        if (tok_int(t, "k") != c.free_parameters)
            fail(std::string(c.id) + ": k drift");
        // The built token rides the SECOND ms row (the of() outcome).
        bool built = false;
        bool have_built = false;
        for (const Row& r : facts) {
            if (r.id == c.id && r.key == "ms" &&
                r.value.find("built ") != std::string::npos) {
                built = r.value.find("built 1") != std::string::npos;
                have_built = true;
            }
        }
        ++cross;
        if (!have_built) fail(std::string(c.id) + ": no built row");
        if (built != (c.built != 0))
            fail(std::string(c.id) + ": built drift");
    }

    for (std::size_t i = 0; i < kalos::test::kRtMachinesN; ++i) {
        const kalos::test::JvmRtMachineCase& c = kalos::test::kRtMachines[i];
        const std::string kind = c.kind == 0 ? "fr" : "dr";
        int seen = 0;
        for (const Row& r : facts) {
            if (r.id != c.id || r.key != kind) continue;
            const std::vector<std::string> t = split(r.value, ' ');
            const std::size_t run = find_tok(t, "run");
            if (run == std::string::npos) continue;  // echoVars companion
            ++seen;
            const int idx = t[run + 1] == "a" ? 0 : t[run + 1] == "b" ? 1 : 2;
            const std::string res_tok = t[find_tok(t, "result") + 1];
            const int res = res_tok == "Changed"
                                ? 0
                                : res_tok == "Unchanged" ? 1 : 2;
            ++cross;
            if (idx >= 0 && idx < 3 && c.runs[idx].result != res)
                fail(std::string(c.id) + ": run" + std::to_string(idx) +
                     " result drift vs corpus");
        }
        if (seen != c.nruns)
            fail(std::string(c.id) + ": run count " + std::to_string(seen) +
                 " vs golden " + std::to_string(c.nruns));
        ++cross;
    }

    for (std::size_t i = 0; i < kalos::test::kRtPgN; ++i) {
        const kalos::test::JvmRtPgCase& c = kalos::test::kRtPg[i];
        const Row* pg = find_row(facts, c.id, "pg");
        if (!pg) {
            fail(std::string(c.id) + ": no pg row in corpus");
            continue;
        }
        const std::vector<std::string> t = split(pg->value, ' ');
        ++cross;
        if (tok_int(t, "ret") != c.ret || tok_int(t, "pass") != c.pass_after ||
            tok_int(t, "round") != c.round_after)
            fail(std::string(c.id) + ": pg ladder drift");
        if (as_bits(tok_d(t, "pcr")) != c.pcr_after)
            fail(std::string(c.id) + ": pcr drift");
        if (as_bits(tok_d(t, "curva")) != c.curva_after)
            fail(std::string(c.id) + ": curva drift");
        if (as_bits(tok_d(t, "refLbp")) != c.ref_lbp_after ||
            as_bits(tok_d(t, "refSe")) != c.ref_se_after)
            fail(std::string(c.id) + ": surviving refStats row drift");
    }

    for (std::size_t i = 0; i < kalos::test::kRtAmN; ++i) {
        const kalos::test::JvmRtAmCase& c = kalos::test::kRtAm[i];
        const std::string id = std::string("am_") + c.spec;
        const Row* am = find_row(facts, id, "am");
        if (!am) {
            fail(id + ": no am row in corpus");
            continue;
        }
        const std::vector<std::string> t = split(am->value, ' ');
        ++cross;
        if (tok_int(t, "checkMu") != c.check_mu)
            fail(id + ": checkMu drift");
        if (as_bits(tok_d(t, "reduceVa")) != c.reduce_va)
            fail(id + ": reduceVa drift");
        if (as_bits(tok_d(t, "ljungBoxLimit")) != c.ljung_box_limit)
            fail(id + ": ljungBoxLimit drift");
    }
}

}  // namespace

int main(int argc, char** argv) {
    const std::string corpus =
        argc > 1 ? argv[1] : "validation/evidence/native/tramo-regression-tests";
    try {
        cross_qualify(corpus);
    } catch (const std::exception& ex) {
        std::cout << "FAIL corpus: " << ex.what() << std::endl;
        return 1;
    }
    kalos::replay::Reporter rep;
    kalos::replay::replay_all(rep);
    std::cout << "verify_tramo_regression_tests: "
              << kalos::test::kRtMsN << " ms, " << kalos::test::kRtMachinesN
              << " machine, " << kalos::test::kRtPgN << " pg, "
              << kalos::test::kRtAmN << " am cases, " << rep.checks
              << " replay checks, " << cross << " corpus cross-checks, "
              << failures << " failures" << std::endl;
    return failures == 0 ? 0 : 1;
}
